  ('csa-u4-q18', 'ap_csa', '4.11', '4', 'P3', 'mcq', 'For `int[][] m = new int[3][5];`, which is true?', '{"A":"`m.length` is 5 and `m[0].length` is 3.","B":"`m.length` is 3 (rows) and `m[0].length` is 5 (columns).","C":"`m.length` is 15.","D":"`m` is jagged."}', 'B', NULL, '`new int[3][5]` is 3 rows × 5 columns: `m.length` = rows = 3, `m[0].length` = columns = 5. Rectangular, not jagged.', NULL, NULL, NULL);
